class Tank {
    private static int made = 0;        // shared by every tank
    private final double capacity;      // each tank has its own
    private double level;

    Tank(double capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity must be positive");
        this.capacity = capacity;
        made++;
    }

    Tank() { this(1000); }              // default size: reuse the checks above

    double getLevel() { return level; }
    double getCapacity() { return capacity; }

    void fill(double litres) {
        if (litres < 0) throw new IllegalArgumentException("negative litres");
        level = Math.min(capacity, level + litres);
    }

    static int count() { return made; }
}

