public class WaterTank {
    private final double capacity;
    private double level;

    public WaterTank(double capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity must be positive");
        this.capacity = capacity;
        this.level = 0;
    }

    public double getCapacity() { return capacity; }
    public double getLevel() { return level; }

    // Adds water; returns how much actually went in (the rest overflows).
    public double fill(double litres) {
        if (litres < 0) throw new IllegalArgumentException("litres can't be negative");
        double added = Math.min(litres, capacity - level);
        level += added;
        return added;
    }

    // Takes water out only if there is enough.
    public boolean use(double litres) {
        if (litres < 0) throw new IllegalArgumentException("litres can't be negative");
        if (litres > level) return false;
        level -= litres;
        return true;
    }

    public double percentFull() {
        return Math.round(level / capacity * 1000) / 10.0;
    }
}

