public class Member {
    private final String name;
    private double savings;

    public Member(String name) {
        this(name, 0);   // one place for the checks
    }

    public Member(String name, double savings) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("name needed");
        if (savings < 0) throw new IllegalArgumentException("savings can't be negative");
        this.name = name.trim();
        this.savings = savings;
    }

    public String getName() { return name; }
    public double getSavings() { return savings; }

    public void deposit(double amount) {
        if (amount <= 0) throw new IllegalArgumentException("deposit must be positive");
        savings += amount;
    }

    public String describe() {
        return name + ": " + savings + " KSh";
    }
}

